def choose_move(observation):
    def sg(key, default=None):
        try:
            return observation.get(key, default)
        except Exception:
            return default

    def sign(n):
        return 1 if n > 0 else (-1 if n < 0 else 0)

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def pos(v, default=(0, 0)):
        try:
            if v is None:
                return default
            if len(v) >= 2:
                return v[0], v[1]
        except Exception:
            pass
        return default

    def dist2(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return clamp_move(sign(b[0] - a[0]), sign(b[1] - a[1]))

    def step_away(a, b):
        return clamp_move(sign(a[0] - b[0]), sign(a[1] - b[1]))

    sx, sy = pos(sg("self_position"), (0, 0))
    ox, oy = pos(sg("opponent_position"), (sx, sy))
    env = sg("environment_name", "resource_collection")
    role = sg("self_role", "pursuer")

    width = sg("grid_width", 0) or 0
    height = sg("grid_height", 0) or 0

    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, height - 1)), (max(0, width - 1), 0), (max(0, width - 1), max(0, height - 1))]
        best = corners[0]
        best_score = -1
        for c in corners:
            s = dist2(c, (ox, oy))
            if s > best_score:
                best_score = s
                best = c
        return step_toward((sx, sy), best)

    if env == "territory_control":
        targets = sg("unclaimed_cells")
        if not targets:
            targets = sg("opponent_territory")
        if not targets:
            targets = sg("neutral_cells")
        if not targets:
            return [0, 0]
        best = None
        best_score = None
        for t in targets:
            tp = pos(t, None)
            if tp is None:
                continue
            sc = dist2((sx, sy), tp)
            if best is None or sc < best_score:
                best = tp
                best_score = sc
        if best is None:
            return [0, 0]
        return step_toward((sx, sy), best)

    resources = sg("resources") or sg("resource_positions") or []
    if not resources:
        return step_away((sx, sy), (ox, oy))

    best = None
    best_score = None
    for r in resources:
        rp = pos(r, None)
        if rp is None:
            continue
        sc = dist2((sx, sy), rp)
        if best is None or sc < best_score:
            best = rp
            best_score = sc

    if best is None:
        return step_away((sx, sy), (ox, oy))

    # Slight denial bias: if opponent is closer to the best resource, take a safer adjacent move.
    if dist2((ox, oy), best) <= dist2((sx, sy), best):
